// generated by beeline from 2 recorded runs.
// GET https://quotes.toscrape.com/page/1/
// 2026-09-20T02:14:59.455Z
//
// this site has no api — the data is rendered straight into the page. so
// this fetches the html and extracts div.quote (10 of them when we
// looked). more brittle than an endpoint: restyle the page and this breaks.
//
// do not edit: re-run `npm run synth -- quotes-page` instead.

import { parse } from "node-html-parser";

export interface QuotesPageRow {
  quote_text: string;
  author: string;
  tags: string;
}

export class QuotesPageClient {
  async call(): Promise<QuotesPageRow[]> {
    const res = await fetch("https://quotes.toscrape.com/page/1/");
    if (!res.ok) throw new Error(`quotes-page: ${res.status} ${res.statusText}`);

    const root = parse(await res.text());
    return root.querySelectorAll("div.quote").map((node) => ({
      "quote_text": pick(node, "span.text"),
      "author": pick(node, "small.author"),
      "tags": pick(node, "div.tags .tag"),
    }));
  }
}

function pick(node: any, selector: string): string {
  const target = selector === "." ? node : node.querySelector(selector);
  return target?.text.trim().replace(/\s+/g, " ") ?? "";
}
